from pathlib import Path
import os,json,subprocess,hashlib,base64,fcntl,tarfile
root=Path('/home/ubuntu/spacepdhcg-collect-final-v287');root.mkdir(exist_ok=False)
base=Path('/home/ubuntu/spacepdhcg-collect-dp-v279');repo=base/'repo'
test=root/'test_gtoc12_gpu_collect_dp.py';test.write_bytes(base64.b64decode(''))
core=base/'core-build/cuda/libspacepdhcg_cuda.so'
env=os.environ.copy();env.update(PYTHONPATH=str(repo/'src')+':'+str(repo/'tests'),SPACEPDHCG_GTOC12_CUDA_LIBRARY=str(core),SPACEPDHCG_GTOC12_DATA='/home/ubuntu/spacepdhcg/gtoc12/benchmarks/gtoc12/data',SPACEPDHCG_GTOC12_GPU_TESTS='1',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
cmd=['/home/ubuntu/spacepdhcg/v1/.venv/bin/python','-c',"import sys,runpy;sys.meta_path=[f for f in sys.meta_path if f.__class__.__module__!='_editable_skbc_spacepdhcg'];runpy.run_module('pytest',run_name='__main__')",str(test),'-q']
with open('/home/ubuntu/.spacepdhcg-gpu.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 with (root/'tests.log').open('w') as log:r=subprocess.run(cmd,cwd=repo,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=45)
report=dict(command=cmd,returncode=r.returncode,test_sha256=hashlib.sha256(test.read_bytes()).hexdigest(),runtime_sha256=hashlib.sha256(core.read_bytes()).hexdigest())
(root/'report.json').write_text(json.dumps(report,indent=2));r.check_returncode()
archive=Path('/tmp/collect-dp-final-v287.tar.gz')
with tarfile.open(archive,'w:gz') as tar:
 for name in ['report.json','run.py','build.log','configure.log','tests.log','memcheck.log','initcheck.log','synccheck.log','racecheck.log','replay.log','replay.json','benchmark.log','benchmark.json']:
  tar.add(base/name,arcname='h100/'+name)
 for name in json.loads((base/'report.json').read_text())['source_sha256']:
  tar.add(repo/name,arcname='source/'+name)
 tar.add(root,arcname='h100-final-tests')
 for v in [280,284,285,286]:
  campaign=Path('/home/ubuntu/spacepdhcg-collect-dp-campaign-v'+str(v))
  assert json.loads((campaign/'report.json').read_text())['complete']
  for name in ['report.json','run.py','campaign.log','output']:
   tar.add(campaign/name,arcname='v'+str(v)+'/'+name)
 for name in ['report.json','run.py']:
  tar.add(Path('/home/ubuntu/spacepdhcg-collect-comparison-v284')/name,arcname='comparison/'+name)
 for name in ['report.json','run.py','campaign.log']:
  tar.add(Path('/home/ubuntu/spacepdhcg-collect-dp-campaign-v281')/name,arcname='rejected-wrapper-v281/'+name)
print(json.dumps(dict(validation=report,archive=str(archive),bytes=archive.stat().st_size,sha256=hashlib.sha256(archive.read_bytes()).hexdigest())))
